// Helpers
const coalesce = (...xs) => {
  for (const x of xs) {
    if (x !== undefined && x !== null && String(x).trim() !== "") return x;
  }
  return "";
};
const num = (v) => {
  if (v === undefined || v === null || v === "") return 0;
  const n = Number(String(v).replace(/[, ]+/g, ""));
  return Number.isFinite(n) ? n : 0;
};

// Source
const src = $json;              // current item (Apify output mapped into n8n)

// Pull values with sensible fallbacks
const username         = coalesce(src.Username, src.username, src.handle);
const fullName         = coalesce(src["Full Name"], src.fullName, src.name);
const followers        = num(coalesce(src.Followers, src.followers, src.followersCount));
const following        = num(coalesce(src.Following, src.following, src.followsCount));
const bio              = coalesce(src.Bio, src.biography, src.bio);
const profilePicUrl    = coalesce(src["Profile Pic URL"], src.profilePicUrl, src.avatar, src.photoUrl);
const website          = coalesce(src.Website, src.website, src.externalUrl, src.url);
const businessCategory = coalesce(src["Business Category"], src.businessCategory, src.category);
const igLink           = coalesce(src["Instagram link "], src["Instagram link"], src.instagramLink,
                                  username ? `https://www.instagram.com/${String(username).replace(/^@/, "")}/` : "");

// Return EXACT shape required
return [
  {
    json: {
      "Username": username || "",
      "Full Name": fullName || "",
      "Followers": followers,
      "Following": following,
      "Bio": bio || "",
      "Profile Pic URL": profilePicUrl || "",
      "Website": website || "",
      "Business Category": businessCategory || "",
      "Instagram link ": igLink || ""
    }
  }
];
